# LlamaIndex-compatible source-type -> allowed relation names.
validation_schema = {}
for _relation, _definition in RELATIONSHIP_SCHEMA.items():
    for _source_type in _definition['source_types']:
        validation_schema.setdefault(_source_type, set()).add(_relation)
validation_schema = {k: sorted(v) for k, v in validation_schema.items()}

# Backward-compatibility mapping from the original prototype schema.
LEGACY_MAPPING = {'NETWORK_FUNCTION': 'NETWORK_FUNCTION', 'NETWORK_ENTITY': 'NETWORK_ENTITY', 'USER_EQUIPMENT': 'USER_EQUIPMENT', 'RADIO_NODE': 'RAN_NODE', 'INTERFACE': 'INTERFACE', 'PROTOCOL': 'PROTOCOL', 'PROCEDURE': 'PROCEDURE', 'SESSION': 'Evaluate during extraction; not promoted to core v1 until recurring evidence justifies it.', 'QOS_CONCEPT': 'QOS_CONCEPT', 'NETWORK_SLICE': 'NETWORK_SLICE', 'CAPABILITY': 'CAPABILITY', 'PARAMETER': 'PARAMETER', 'INFORMATION_ELEMENT': 'INFORMATION_ELEMENT', 'MESSAGE': 'MESSAGE', 'REQUIREMENT': 'REQUIREMENT'}

# Provenance fields recommended on every extracted entity/fact.
PROVENANCE_PROPERTIES = ['source_document', 'specification', 'version', 'section', 'page', 'chunk_id', 'evidence', 'confidence']

# Extraction guidance.
EXTRACTION_RULES = ['Keep ontology types small and reusable; represent O-DU/O-CU/O-RU, Near-RT RIC/Non-RT RIC, E2/O1/O2/A1, etc. as instances/concepts under reusable types.', 'Use explicit properties for attributes that are useful for answering questions rather than turning every attribute into a new node type.', 'Treat YANG structure as first-class graph structure because the corpus contains model names, paths, containers/lists/leaves, types, imports, revisions, and augmentations.', 'Attach provenance/evidence to extracted facts so graph retrieval can return the original supporting text.', 'Use benchmark-driven refinement after initial extraction; this schema is candidate v1, not a final immutable ontology.', 'Resolve synonyms and duplicates through canonical names, aliases, source evidence, type-aware matching, and semantic review rather than string matching alone.']


def get_entity_types():
    return list(ENTITY_SCHEMA.keys())


def get_relationship_types():
    return list(RELATIONSHIP_SCHEMA.keys())


def is_valid_relationship(source_type: str, relationship_type: str, target_type: str) -> bool:
    definition = RELATIONSHIP_SCHEMA.get(relationship_type)
    if not definition:
        return False
    source_types = definition.get("source_types", [])
    target_types = definition.get("target_types", [])
    return (
        (not source_types or source_type in source_types)
        and (not target_types or target_type in target_types)
    )
